"use client";

import { FlowDiagram } from "@diax/react";
import { Activity, Box, Cloud, Database, Lock, type LucideIcon, Search } from "lucide-react";

interface GlassNodeProps {
  icon: LucideIcon;
  title: string;
  isCore?: boolean;
}

// Beautiful premium glassmorphic node
const GlassNode = ({ icon: Icon, title, isCore = false }: GlassNodeProps) => {
  return (
    <div
      className={`group relative flex flex-col items-center justify-center min-w-[140px] px-6 py-5 rounded-[24px] border overflow-hidden backdrop-blur-2xl transition-all duration-500 hover:scale-110 shadow-2xl ${
        isCore
          ? "border-[#5E6AD2]/30 bg-[#5E6AD2]/10 shadow-[#5E6AD2]/20 hover:border-[#5E6AD2]/60 hover:bg-[#5E6AD2]/20"
          : "border-white/10 bg-white/5 hover:border-white/20 hover:bg-white/10"
      }`}
    >
      {/* Dynamic light reflection line on top */}
      <div className="absolute inset-x-0 top-0 h-px bg-gradient-to-r from-transparent via-white/40 to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>

      <div className="relative mb-3 flex h-14 w-14 items-center justify-center rounded-2xl bg-gradient-to-b from-white/10 to-transparent shadow-inner">
        <Icon
          className={`h-7 w-7 ${isCore ? "text-white drop-shadow-[0_0_8px_rgba(94,106,210,0.8)]" : "text-white/80"}`}
        />
      </div>

      <h3 className="text-[13px] font-bold tracking-widest text-white uppercase opacity-90">
        {title}
      </h3>
    </div>
  );
};

export default function SaaSGlassArch() {
  return (
    <div className="w-full h-full min-h-[600px] flex items-center justify-center relative overflow-hidden bg-black py-10">
      {/* Complex ambient background for glassmorphism */}
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(255,255,255,0.02)_1px,transparent_0)] bg-[size:32px_32px]"></div>
      <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-gradient-to-bl from-indigo-600/30 to-transparent blur-[120px] rounded-full pointer-events-none -translate-y-1/2 translate-x-1/2" />
      <div className="absolute bottom-0 left-0 w-[600px] h-[600px] bg-gradient-to-tr from-cyan-600/20 to-transparent blur-[150px] rounded-full pointer-events-none translate-y-1/3 -translate-x-1/3" />
      <div className="absolute top-1/2 left-1/2 -mt-24 -ml-24 w-48 h-48 bg-[#5E6AD2]/40 rounded-full blur-[100px] pointer-events-none" />

      <FlowDiagram
        nodes={[
          {
            id: "edge",
            content: <GlassNode icon={Cloud} title="Edge CDN" />,
          },
          {
            id: "gateway",
            content: <GlassNode icon={Box} title="API Gateway" isCore />,
          },
          {
            id: "auth",
            content: <GlassNode icon={Lock} title="Identity" />,
          },
          {
            id: "search",
            content: <GlassNode icon={Search} title="Search Engine" />,
          },
          {
            id: "db",
            content: <GlassNode icon={Database} title="Primary DB" isCore />,
          },
          {
            id: "analytics",
            content: <GlassNode icon={Activity} title="Analytics" />,
          },
        ]}
        relations={[
          "edge->|TCP|gateway",
          "gateway->auth",
          "gateway->search",
          "gateway->db",
          "db->analytics", // ETL
          "search->analytics",
        ]}
        direction="horizontal"
        centered
        density="spacious"
      />
    </div>
  );
}
